from __future__ import annotations; import os; from datetime import date; from decimal import Decimal; import psycopg; import pytest; from data_engine.config import settings; from data_engine.quality.invariants import INVARIANTS, check; from data_engine.quality.vendor_oracle import Drift, gross_profit, latest_across_variants, period_reporting, revenue; _CUTOFF = date(2026, 7, 27)
def _annual(end: str, start: str, val: object, filed: str) -> dict: return {"end": end, "start": start, "val": val, "filed": filed}
def _facts(**concepts: list[dict]) -> dict: return {"facts": {"us-gaap": {name: {"units": {"USD": rows}} for name, rows in concepts.items()}}}
def test_latest_period_wins_across_variants_not_declaration_order() -> None: facts = _facts( Revenues=[_annual("2018-09-29", "2017-10-01", 265595000000, "2018-11-05")], RevenueFromContractWithCustomerExcludingAssessedTax=[ _annual("2025-09-27", "2024-09-29", 416161000000, "2025-10-31") ], ); found = latest_across_variants( facts, ("Revenues", "RevenueFromContractWithCustomerExcludingAssessedTax"), "USD", _CUTOFF ); assert found is not None; assert found.value == Decimal("416161000000"); assert found.period_end == date(2025, 9, 27)
def test_declaration_order_does_not_change_the_answer() -> None: facts = _facts( Revenues=[_annual("2018-09-29", "2017-10-01", 265595000000, "2018-11-05")], SalesRevenueNet=[_annual("2025-09-27", "2024-09-29", 416161000000, "2025-10-31")], ); forward = latest_across_variants(facts, ("Revenues", "SalesRevenueNet"), "USD", _CUTOFF); reverse = latest_across_variants(facts, ("SalesRevenueNet", "Revenues"), "USD", _CUTOFF); assert forward is not None and reverse is not None; assert forward.value == reverse.value == Decimal("416161000000")
def test_a_stale_reported_gross_profit_loses_to_a_current_derivation() -> None: facts = _facts( GrossProfit=[_annual("2009-12-31", "2009-01-01", 5531000000, "2010-01-29")], RevenueFromContractWithCustomerExcludingAssessedTax=[ _annual("2025-12-31", "2025-01-01", 716924000000, "2026-02-06") ], CostOfGoodsAndServicesSold=[_annual("2025-12-31", "2025-01-01", 356414000000, "2026-02-06")], ); found = gross_profit(facts, _CUTOFF); assert found is not None; assert found.period_end == date(2025, 12, 31); assert found.value == Decimal("360510000000")
def test_a_current_reported_gross_profit_beats_an_older_derivation() -> None: facts = _facts( GrossProfit=[_annual("2025-12-31", "2025-01-01", 195201000000, "2026-02-01")], Revenues=[_annual("2024-12-31", "2024-01-01", 900, "2025-02-01")], CostOfRevenue=[_annual("2024-12-31", "2024-01-01", 400, "2025-02-01")], ); found = gross_profit(facts, _CUTOFF); assert found is not None; assert found.value == Decimal("195201000000")
def test_facts_filed_after_the_cutoff_are_not_knowable() -> None: facts = _facts( Revenues=[ _annual("2024-12-31", "2024-01-01", 100, "2025-02-01"), _annual("2025-12-31", "2025-01-01", 200, "2026-08-01"), ] ); found = latest_across_variants(facts, ("Revenues",), "USD", _CUTOFF); assert found is not None; assert found.value == Decimal("100")
def test_a_figure_is_knowable_from_the_day_its_winning_fact_was_filed() -> None: facts = _facts( Revenues=[ _annual("2024-12-31", "2024-01-01", 100, "2025-02-01"), _annual("2025-12-31", "2025-01-01", 200, "2026-02-05"), ], CostOfRevenue=[_annual("2025-12-31", "2025-01-01", 50, "2026-03-09")], ); revenue_fact = revenue(facts, _CUTOFF); derived = gross_profit(facts, _CUTOFF); assert revenue_fact is not None and derived is not None; assert (revenue_fact.value, revenue_fact.filed) == (Decimal(200), date(2026, 2, 5)); assert (derived.value, derived.filed) == (Decimal(150), date(2026, 3, 9))
def test_quarterly_spans_never_win_over_annual_ones() -> None: facts = _facts( Revenues=[ _annual("2025-12-31", "2025-01-01", 900, "2026-02-01"), _annual("2026-03-31", "2026-01-01", 250, "2026-04-20"), ] ); found = latest_across_variants(facts, ("Revenues",), "USD", _CUTOFF); assert found is not None; assert found.value == Decimal("900")
def test_an_issuer_that_reports_nothing_yields_nothing() -> None: assert latest_across_variants(_facts(), ("Revenues",), "USD", _CUTOFF) is None; assert gross_profit(_facts(), _CUTOFF) is None
@pytest.fixture
def connection():
    try: active = psycopg.connect(settings.database_url, connect_timeout=3, autocommit=False)
    except psycopg.OperationalError as error:
        if os.environ.get("DATABASE_URL") or os.environ.get("TRUEALPHA_REQUIRE_RUNTIME"): pytest.fail(f"configured Postgres is unreachable: {error}", pytrace=False)
        pytest.skip("no local Postgres; CI runs the required integration coverage")
    try: active.execute("select 1"); yield active
    finally: active.rollback(); active.close()
def test_every_invariant_executes_and_returns_a_count(connection) -> None: assert len(INVARIANTS) > 0; results = check(connection); assert len(results) == len(INVARIANTS); assert all(isinstance(item.violations, int) for item in results)
def test_each_invariant_declares_why_it_needs_no_domain_knowledge() -> None:
    assert len(INVARIANTS) > 0
    for invariant in INVARIANTS: assert invariant.self_evident_because, f"{invariant.id} must say why it is self-evident"; assert invariant.statement
def test_staleness_is_measured_from_the_period_mart_actually_used() -> None: facts = _facts( Revenues=[_annual("2018-09-29", "2017-10-01", 265595000000, "2018-11-05")], RevenueFromContractWithCustomerExcludingAssessedTax=[ _annual("2025-09-27", "2024-09-29", 416161000000, "2025-10-31") ], ); concepts = ("Revenues", "RevenueFromContractWithCustomerExcludingAssessedTax"); drift = Drift( ticker="AAPL", field="revenue", mart_value=Decimal("265595000000"), vendor=latest_across_variants(facts, concepts, "USD", _CUTOFF), cutoff=_CUTOFF, mart_period_end=period_reporting(facts, concepts, Decimal("265595000000"), _CUTOFF), ); assert not drift.agrees; assert drift.mart_period_end == date(2018, 9, 29); assert drift.staleness_years == 7
def test_a_value_matching_no_vendor_period_claims_no_staleness() -> None: facts = _facts(Revenues=[_annual("2025-12-31", "2025-01-01", 900, "2026-02-01")]); assert period_reporting(facts, ("Revenues",), Decimal("12345"), _CUTOFF) is None
def test_the_origin_registry_covers_the_current_parser_version() -> None: from data_engine.datahub.production_topt.parser_identity import PARSER_VERSION; from data_engine.datahub.production_topt.twelve_data_origin import PARSER_VERSION as SECOND_ORIGIN_VERSION; from data_engine.datahub.quality_report import _SOURCE_BY_PARSER; assert PARSER_VERSION in _SOURCE_BY_PARSER, "primary parser vintage is not mapped to an origin group"; assert SECOND_ORIGIN_VERSION in _SOURCE_BY_PARSER, "second origin's parser vintage is not mapped"; assert len({group for _, group, _ in _SOURCE_BY_PARSER.values()}) >= 2, ( "reconciliation needs at least two distinct origin groups to compare" )
def test_the_origin_registry_covers_every_parser_version_ever_shipped() -> None: from data_engine.datahub.production_topt.parser_identity import PARSER_VERSION, PARSER_VERSION_HISTORY; from data_engine.datahub.quality_report import _SOURCE_BY_PARSER; missing = [vintage for vintage in PARSER_VERSION_HISTORY if vintage not in _SOURCE_BY_PARSER]; assert not missing, f"historical parser vintages dropped out of the origin registry: {missing}"; assert PARSER_VERSION == PARSER_VERSION_HISTORY[-1]; assert len(set(PARSER_VERSION_HISTORY)) == len(PARSER_VERSION_HISTORY), "duplicate vintage in the history"
